STORY = [('kawada', 'お金は貸せませんよ。トシがあなたにお金を貸すのを許してくれないと思うんで。', "I won't lend you money, because I don't think Toshi would forgive me if I lent you cash.", [(418, 'お金は貸せませんよ'), (419, 'トシが'), (420, 'あなたに お金を貸すのを 許してくれないと思うんで')], ''), ('kawada', 'あなたもともとセールスマンだったんですよね？僕に何か売りつけてくださいよ。', 'You were originally a salesman, right? Try selling something to me.', [(423, 'あなた もともと セールスマンだったんですよね'), (427, '僕に何か売りつけてくださいよ')], ''), ('kawada', '貸すのは無理でも、少しぐらいならキャッシュで買い取りますよ。', "Lending is out of the question, but I'll gladly buy something off you in cash.", [(428, '貸すのは無理でも 少しぐらいなら キャッシュで買い取りますよ')], ''), ('kawada', 'この石、あなたならどう売りますか？', 'This pebble right here—how would you sell it?', [(430, 'この石'), (431, 'あなたなら どう売りますか')], ''), ('muranishi', 'これはね、世界中の海を渡り歩いてこの砂浜にようやくたどり着いた、世界に一つだけの石なんですよ。', 'This stone traveled across the oceans of the world to finally reach this beach—a one-of-a-kind stone in all the world!', [(435, 'これはね 世界中の海を渡り歩いて'), (437, 'この砂浜に ようやく たどり着いた'), (438, '石なんですよ')], 'spelled numeral in kanji'), ('muranishi', '荒波にもまれて方々にぶつかって、なめられてできたこのきれいなフォルム、非常にセクシーでございましょ？', "Tossed by rough waves and licked smooth millions of times into this lovely form—isn't it remarkably sexy?", [(440, '荒波にもまれて 方々にぶつかって'), (443, 'なめられてできた このきれいなフォルム'), (444, '非常にセクシーでございましょ')], ''), ('muranishi', '言ってしまえばね、地球なんですよ、小さな地球。ご自身の手で感じてみたいと思いませんか？', "Simply put, it is the Earth—a tiny Earth! Wouldn't you like to feel its hidden power in your own hand?", [(451, '言ってしまえばね'), (452, '地球なんですよ'), (452, '小さな地球'), (454, 'ご自身の手で 感じてみたいと思いませんか')], ''), ('kawada', 'いいんですか？ああ確かに。', 'May I? Ah, it really does fit.', [(455, 'いいんですか'), (457, 'ああ 確かに')], ''), ('muranishi', 'ガラスの靴がね、シンデレラの足にピタッとハマったように、川田さんの手に今ピタッとハマってますよ。', "Just as the glass slipper fit snugly onto Cinderella's foot, this stone fits right into your palm!", [(459, 'ガラスの靴がね シンデレラの足に ピタッとハマったように'), (460, '川田さんの手に 今 ピタッとハマってますよ')], ''), ('muranishi', 'これはね川田さん、私が渡したんじゃないんです。石の意思なんですよ。', "Mr. Kawada, I wasn't the one who handed it to you—it was the stone's own will!", [(466, 'これはね 川田さん 私が渡したんじゃないんです'), (468, '石の意思なんですよ')], ''), ('muranishi', '大事なとこでかんでしまう。', 'And I tripped over my tongue right at the punchline!', [(469, '大事なとこで かんでしまう')], ''), ('muranishi', '今日は地球がキャンペーンしてくれてますよ！すばらしい！', 'Today the Earth itself is running a special promotion for us! Magnificent!', [(480, '今日は地球が キャンペーンしてくれてますよ'), (488, 'すばらしい')], '')]
